@Service @Transactional
public class LdFoundationServiceImpl implements LdFoundationService {
 private final LdGovernancePolicyRepository policies;private final LdGovernancePolicyVersionRepository policyVersions;private final LdInterventionRepository interventions;private final LdInterventionVersionRepository interventionVersions;private final LdProviderRepository providers;private final LdResourcePersonRepository resourcePersons;private final LdEvaluationFrameworkRepository frameworks;private final LdEvaluationFrameworkVersionRepository frameworkVersions;private final LdEvaluationLevelRepository levels;private final PrimeHrAuditService audit;
 public LdFoundationServiceImpl(LdGovernancePolicyRepository p,LdGovernancePolicyVersionRepository pv,LdInterventionRepository i,LdInterventionVersionRepository iv,LdProviderRepository pr,LdResourcePersonRepository rp,LdEvaluationFrameworkRepository f,LdEvaluationFrameworkVersionRepository fv,LdEvaluationLevelRepository l,PrimeHrAuditService a){policies=p;policyVersions=pv;interventions=i;interventionVersions=iv;providers=pr;resourcePersons=rp;frameworks=f;frameworkVersions=fv;levels=l;audit=a;}

 @Override @Transactional(readOnly=true)public List<PolicyResponse>policies(String agency){return policyVersions.findByAgencyIdOrderByCreatedAtDesc(agency).stream().map(v->policyResponse(agency,v)).toList();}
 @Override @Transactional(readOnly=true)public PolicyResponse policy(String agency,String id){return policyResponse(agency,policyVersion(agency,id));}
 @Override public PolicyResponse createPolicy(String agency,PolicyInput r,String c){newRecord(r.recordVersion());String code=normalize(r.code());if(policies.existsByAgencyIdAndNormalizedCode(agency,code))throw new IllegalArgumentException("L&D governance policy code already exists");LdGovernancePolicy root=policies.saveAndFlush(new LdGovernancePolicy(agency,r.code()));LdGovernancePolicyVersion v=policyVersions.saveAndFlush(policyVersion(agency,root.getId(),1,null,r));PolicyResponse after=policyResponse(agency,v);record(agency,"CREATE_LD_POLICY_DRAFT","LD_GOVERNANCE_POLICY_VERSION",v,after,null,c);return after;}
 @Override public PolicyResponse updatePolicy(String agency,String id,PolicyInput r,String c){LdGovernancePolicyVersion v=policyVersion(agency,id);version(v.getVersion(),r.recordVersion());stableCode(policyRoot(agency,v.getPolicyId()).getCode(),r.code());PolicyResponse before=policyResponse(agency,v);v.update(r.title(),r.description(),r.legalBasis(),r.planningYearStartMonth(),r.minimumPlannedInterventions(),r.supervisoryMinimumHours(),r.behaviorEvaluationMinDays(),r.behaviorEvaluationMaxDays(),r.requiresIdp(),r.requiresSupervisorRecommendation(),r.requiresFinalApproval());v=policyVersions.saveAndFlush(v);PolicyResponse after=policyResponse(agency,v);record(agency,"UPDATE_LD_POLICY_DRAFT","LD_GOVERNANCE_POLICY_VERSION",v,after,before,c);return after;}
 @Override public PolicyResponse revisePolicy(String agency,String id,DefinitionTransition r,String c){LdGovernancePolicyVersion prior=policyVersion(agency,id);version(prior.getVersion(),r.recordVersion());published(prior.getStatus());int next=nextPolicyVersion(agency,prior.getPolicyId());LdGovernancePolicyVersion v=policyVersions.saveAndFlush(new LdGovernancePolicyVersion(agency,prior.getPolicyId(),next,prior.getId(),prior.getTitle(),prior.getDescription(),prior.getLegalBasis(),prior.getPlanningYearStartMonth(),prior.getMinimumPlannedInterventions(),prior.getSupervisoryMinimumHours(),prior.getBehaviorEvaluationMinDays(),prior.getBehaviorEvaluationMaxDays(),prior.isRequiresIdp(),prior.isRequiresSupervisorRecommendation(),prior.isRequiresFinalApproval()));PolicyResponse after=policyResponse(agency,v);audit.record(agency,"CREATE_LD_POLICY_REVISION","LD_GOVERNANCE_POLICY_VERSION",v.getId(),next,v.getVersion(),null,after,r.reason(),c);return after;}
 @Override public PolicyResponse publishPolicy(String agency,String id,PublishTransition r,String c){LdGovernancePolicyVersion v=policyVersion(agency,id);version(v.getVersion(),r.recordVersion());LdGovernancePolicyVersion prior=v.getSupersedesId()==null?null:policyVersion(agency,v.getSupersedesId());validatePublish(r,prior,policyVersions.findByAgencyIdAndStatus(agency,LdDefinitionStatus.PUBLISHED),v.getId());PolicyResponse before=policyResponse(agency,v);Instant now=Instant.now();v.publish(r.effectiveFrom(),r.effectiveTo(),audit.currentActor(),now);v=policyVersions.saveAndFlush(v);if(prior!=null){prior.supersede(r.effectiveFrom(),audit.currentActor(),now);policyVersions.saveAndFlush(prior);}PolicyResponse after=policyResponse(agency,v);audit.record(agency,"PUBLISH_LD_POLICY","LD_GOVERNANCE_POLICY_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}
 @Override public PolicyResponse retirePolicy(String agency,String id,DefinitionTransition r,String c){LdGovernancePolicyVersion v=policyVersion(agency,id);version(v.getVersion(),r.recordVersion());PolicyResponse before=policyResponse(agency,v);v.retire(audit.currentActor(),r.reason(),Instant.now());v=policyVersions.saveAndFlush(v);PolicyResponse after=policyResponse(agency,v);audit.record(agency,"RETIRE_LD_POLICY","LD_GOVERNANCE_POLICY_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}
 @Override @Transactional(readOnly=true)public PolicyResponse effectivePolicy(String agency,LocalDate on){return policyVersions.findByAgencyIdAndStatus(agency,LdDefinitionStatus.PUBLISHED).stream().filter(v->v.effectiveOn(on)).findFirst().map(v->policyResponse(agency,v)).orElseThrow(()->new ResourceNotFoundException("No L&D governance policy is effective on the requested date"));}

 @Override @Transactional(readOnly=true)public List<InterventionResponse>interventions(String agency){return interventionVersions.findByAgencyIdOrderByCreatedAtDesc(agency).stream().map(v->interventionResponse(agency,v)).toList();}
 @Override @Transactional(readOnly=true)public InterventionResponse intervention(String agency,String id){return interventionResponse(agency,interventionVersion(agency,id));}
 @Override public InterventionResponse createIntervention(String agency,InterventionInput r,String c){newRecord(r.recordVersion());String code=normalize(r.code());if(interventions.existsByAgencyIdAndNormalizedCode(agency,code))throw new IllegalArgumentException("L&D intervention code already exists");LdIntervention root=interventions.saveAndFlush(new LdIntervention(agency,r.code()));LdInterventionVersion v=interventionVersions.saveAndFlush(interventionVersion(agency,root.getId(),1,null,r));InterventionResponse after=interventionResponse(agency,v);record(agency,"CREATE_LD_INTERVENTION_DRAFT","LD_INTERVENTION_VERSION",v,after,null,c);return after;}
 @Override public InterventionResponse updateIntervention(String agency,String id,InterventionInput r,String c){LdInterventionVersion v=interventionVersion(agency,id);version(v.getVersion(),r.recordVersion());stableCode(interventionRoot(agency,v.getInterventionId()).getCode(),r.code());InterventionResponse before=interventionResponse(agency,v);v.update(r.title(),r.description(),r.category(),r.defaultModality(),r.intendedOutcomes(),r.deliveryRequirements());v=interventionVersions.saveAndFlush(v);InterventionResponse after=interventionResponse(agency,v);record(agency,"UPDATE_LD_INTERVENTION_DRAFT","LD_INTERVENTION_VERSION",v,after,before,c);return after;}
 @Override public InterventionResponse reviseIntervention(String agency,String id,DefinitionTransition r,String c){LdInterventionVersion prior=interventionVersion(agency,id);version(prior.getVersion(),r.recordVersion());published(prior.getStatus());int next=interventionVersions.findByAgencyIdAndInterventionIdOrderByDefinitionVersionDesc(agency,prior.getInterventionId()).stream().mapToInt(LdInterventionVersion::getDefinitionVersion).max().orElse(0)+1;LdInterventionVersion v=interventionVersions.saveAndFlush(new LdInterventionVersion(agency,prior.getInterventionId(),next,prior.getId(),prior.getTitle(),prior.getDescription(),prior.getCategory(),prior.getDefaultModality(),prior.getIntendedOutcomes(),prior.getDeliveryRequirements()));InterventionResponse after=interventionResponse(agency,v);audit.record(agency,"CREATE_LD_INTERVENTION_REVISION","LD_INTERVENTION_VERSION",v.getId(),next,v.getVersion(),null,after,r.reason(),c);return after;}
 @Override public InterventionResponse publishIntervention(String agency,String id,PublishTransition r,String c){LdInterventionVersion v=interventionVersion(agency,id);version(v.getVersion(),r.recordVersion());String interventionId=v.getInterventionId();LdInterventionVersion prior=v.getSupersedesId()==null?null:interventionVersion(agency,v.getSupersedesId());validatePublish(r,prior,interventionVersions.findByAgencyIdAndStatus(agency,LdDefinitionStatus.PUBLISHED).stream().filter(x->x.getInterventionId().equals(interventionId)).toList(),v.getId());InterventionResponse before=interventionResponse(agency,v);Instant now=Instant.now();v.publish(r.effectiveFrom(),r.effectiveTo(),audit.currentActor(),now);v=interventionVersions.saveAndFlush(v);if(prior!=null){prior.supersede(r.effectiveFrom(),audit.currentActor(),now);interventionVersions.saveAndFlush(prior);}InterventionResponse after=interventionResponse(agency,v);audit.record(agency,"PUBLISH_LD_INTERVENTION","LD_INTERVENTION_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}
 @Override public InterventionResponse retireIntervention(String agency,String id,DefinitionTransition r,String c){LdInterventionVersion v=interventionVersion(agency,id);version(v.getVersion(),r.recordVersion());InterventionResponse before=interventionResponse(agency,v);v.retire(audit.currentActor(),r.reason(),Instant.now());v=interventionVersions.saveAndFlush(v);InterventionResponse after=interventionResponse(agency,v);audit.record(agency,"RETIRE_LD_INTERVENTION","LD_INTERVENTION_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}

 @Override @Transactional(readOnly=true)public List<ProviderResponse>providers(String agency){return providers.findByAgencyIdOrderByNameAsc(agency).stream().map(this::providerResponse).toList();}
 @Override @Transactional(readOnly=true)public ProviderResponse provider(String agency,String id){return providerResponse(providerEntity(agency,id));}
 @Override public ProviderResponse createProvider(String agency,ProviderInput r,String c){newRecord(r.recordVersion());if(providers.existsByAgencyIdAndNormalizedCode(agency,normalize(r.code())))throw new IllegalArgumentException("L&D provider code already exists");LdProvider p=providers.saveAndFlush(new LdProvider(agency,r.code(),r.name(),r.providerType(),r.accreditationReference(),r.contactDetails()));ProviderResponse after=providerResponse(p);record(agency,"CREATE_LD_PROVIDER","LD_PROVIDER",p,after,null,c);return after;}
 @Override public ProviderResponse updateProvider(String agency,String id,ProviderInput r,String c){LdProvider p=providerEntity(agency,id);version(p.getVersion(),r.recordVersion());if(providers.existsByAgencyIdAndNormalizedCodeAndIdNot(agency,normalize(r.code()),id))throw new IllegalArgumentException("L&D provider code already exists");ProviderResponse before=providerResponse(p);p.update(r.code(),r.name(),r.providerType(),r.accreditationReference(),r.contactDetails());p=providers.saveAndFlush(p);ProviderResponse after=providerResponse(p);record(agency,"UPDATE_LD_PROVIDER","LD_PROVIDER",p,after,before,c);return after;}
 @Override public ProviderResponse providerStatus(String agency,String id,RegistryTransition r,boolean active,String c){LdProvider p=providerEntity(agency,id);version(p.getVersion(),r.recordVersion());if(!active&&resourcePersons.existsByAgencyIdAndProviderIdAndStatus(agency,id,LdResourcePerson.Status.ACTIVE))throw new IllegalLifecycleTransitionException("A provider assigned to an active resource person cannot be deactivated");ProviderResponse before=providerResponse(p);if(active)p.activate();else p.deactivate();p=providers.saveAndFlush(p);ProviderResponse after=providerResponse(p);audit.record(agency,active?"ACTIVATE_LD_PROVIDER":"DEACTIVATE_LD_PROVIDER","LD_PROVIDER",id,null,p.getVersion(),before,after,r.reason(),c);return after;}

 @Override @Transactional(readOnly=true)public List<ResourcePersonResponse>resourcePersons(String agency){return resourcePersons.findByAgencyIdOrderByDisplayNameAsc(agency).stream().map(this::resourcePersonResponse).toList();}
 @Override @Transactional(readOnly=true)public ResourcePersonResponse resourcePerson(String agency,String id){return resourcePersonResponse(resourcePersonEntity(agency,id));}
 @Override public ResourcePersonResponse createResourcePerson(String agency,ResourcePersonInput r,String c){newRecord(r.recordVersion());if(resourcePersons.existsByAgencyIdAndNormalizedCode(agency,normalize(r.code())))throw new IllegalArgumentException("L&D resource person code already exists");validateProvider(agency,r.providerId());LdResourcePerson p=resourcePersons.saveAndFlush(new LdResourcePerson(agency,r.code(),r.personSource(),r.employeeNo(),r.displayName(),r.providerId(),r.expertise(),r.credentials(),r.contactDetails()));ResourcePersonResponse after=resourcePersonResponse(p);record(agency,"CREATE_LD_RESOURCE_PERSON","LD_RESOURCE_PERSON",p,after,null,c);return after;}
 @Override public ResourcePersonResponse updateResourcePerson(String agency,String id,ResourcePersonInput r,String c){LdResourcePerson p=resourcePersonEntity(agency,id);version(p.getVersion(),r.recordVersion());if(resourcePersons.existsByAgencyIdAndNormalizedCodeAndIdNot(agency,normalize(r.code()),id))throw new IllegalArgumentException("L&D resource person code already exists");validateProvider(agency,r.providerId());ResourcePersonResponse before=resourcePersonResponse(p);p.update(r.code(),r.personSource(),r.employeeNo(),r.displayName(),r.providerId(),r.expertise(),r.credentials(),r.contactDetails());p=resourcePersons.saveAndFlush(p);ResourcePersonResponse after=resourcePersonResponse(p);record(agency,"UPDATE_LD_RESOURCE_PERSON","LD_RESOURCE_PERSON",p,after,before,c);return after;}
 @Override public ResourcePersonResponse resourcePersonStatus(String agency,String id,RegistryTransition r,boolean active,String c){LdResourcePerson p=resourcePersonEntity(agency,id);version(p.getVersion(),r.recordVersion());ResourcePersonResponse before=resourcePersonResponse(p);if(active)p.activate();else p.deactivate();p=resourcePersons.saveAndFlush(p);ResourcePersonResponse after=resourcePersonResponse(p);audit.record(agency,active?"ACTIVATE_LD_RESOURCE_PERSON":"DEACTIVATE_LD_RESOURCE_PERSON","LD_RESOURCE_PERSON",id,null,p.getVersion(),before,after,r.reason(),c);return after;}

 @Override @Transactional(readOnly=true)public List<EvaluationFrameworkResponse>evaluationFrameworks(String agency){return frameworkVersions.findByAgencyIdOrderByCreatedAtDesc(agency).stream().map(v->frameworkResponse(agency,v)).toList();}
 @Override @Transactional(readOnly=true)public EvaluationFrameworkResponse evaluationFramework(String agency,String id){return frameworkResponse(agency,frameworkVersion(agency,id));}
 @Override public EvaluationFrameworkResponse createEvaluationFramework(String agency,EvaluationFrameworkInput r,String c){newRecord(r.recordVersion());if(frameworks.existsByAgencyIdAndNormalizedCode(agency,normalize(r.code())))throw new IllegalArgumentException("L&D evaluation framework code already exists");LdEvaluationFramework root=frameworks.saveAndFlush(new LdEvaluationFramework(agency,r.code()));LdEvaluationFrameworkVersion v=frameworkVersions.saveAndFlush(new LdEvaluationFrameworkVersion(agency,root.getId(),1,null,r.title(),r.description(),r.legalBasis()));EvaluationFrameworkResponse after=frameworkResponse(agency,v);record(agency,"CREATE_LD_EVALUATION_FRAMEWORK_DRAFT","LD_EVALUATION_FRAMEWORK_VERSION",v,after,null,c);return after;}
 @Override public EvaluationFrameworkResponse updateEvaluationFramework(String agency,String id,EvaluationFrameworkInput r,String c){LdEvaluationFrameworkVersion v=frameworkVersion(agency,id);version(v.getVersion(),r.recordVersion());stableCode(frameworkRoot(agency,v.getFrameworkId()).getCode(),r.code());EvaluationFrameworkResponse before=frameworkResponse(agency,v);v.update(r.title(),r.description(),r.legalBasis());v=frameworkVersions.saveAndFlush(v);EvaluationFrameworkResponse after=frameworkResponse(agency,v);record(agency,"UPDATE_LD_EVALUATION_FRAMEWORK_DRAFT","LD_EVALUATION_FRAMEWORK_VERSION",v,after,before,c);return after;}
 @Override public EvaluationFrameworkResponse replaceEvaluationLevels(String agency,String id,EvaluationLevelsInput r,String c){LdEvaluationFrameworkVersion v=frameworkVersion(agency,id);version(v.getVersion(),r.recordVersion());validateLevels(r.levels());EvaluationFrameworkResponse before=frameworkResponse(agency,v);levels.deleteByAgencyIdAndFrameworkVersionId(agency,id);levels.flush();levels.saveAll(r.levels().stream().map(x->new LdEvaluationLevel(agency,id,x.levelType(),x.required(),x.dueAfterDays(),x.scoreMethod(),x.passingScore(),x.evidenceRequirements(),x.instrumentGuidance(),x.displayOrder())).toList());levels.flush();v.levelsChanged();v=frameworkVersions.saveAndFlush(v);EvaluationFrameworkResponse after=frameworkResponse(agency,v);record(agency,"REPLACE_LD_EVALUATION_LEVELS","LD_EVALUATION_FRAMEWORK_VERSION",v,after,before,c);return after;}
 @Override public EvaluationFrameworkResponse reviseEvaluationFramework(String agency,String id,DefinitionTransition r,String c){LdEvaluationFrameworkVersion prior=frameworkVersion(agency,id);version(prior.getVersion(),r.recordVersion());published(prior.getStatus());int next=frameworkVersions.findByAgencyIdAndFrameworkIdOrderByDefinitionVersionDesc(agency,prior.getFrameworkId()).stream().mapToInt(LdEvaluationFrameworkVersion::getDefinitionVersion).max().orElse(0)+1;LdEvaluationFrameworkVersion v=frameworkVersions.saveAndFlush(new LdEvaluationFrameworkVersion(agency,prior.getFrameworkId(),next,prior.getId(),prior.getTitle(),prior.getDescription(),prior.getLegalBasis()));String newVersionId=v.getId();List<LdEvaluationLevel> source=levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrderAsc(agency,id);levels.saveAll(source.stream().map(x->new LdEvaluationLevel(agency,newVersionId,x.getLevelType(),x.isRequired(),x.getDueAfterDays(),x.getScoreMethod(),x.getPassingScore(),x.getEvidenceRequirements(),x.getInstrumentGuidance(),x.getDisplayOrder())).toList());if(!source.isEmpty()){v.levelsChanged();v=frameworkVersions.saveAndFlush(v);}EvaluationFrameworkResponse after=frameworkResponse(agency,v);audit.record(agency,"CREATE_LD_EVALUATION_FRAMEWORK_REVISION","LD_EVALUATION_FRAMEWORK_VERSION",v.getId(),next,v.getVersion(),null,after,r.reason(),c);return after;}
 @Override public EvaluationFrameworkResponse publishEvaluationFramework(String agency,String id,PublishTransition r,String c){LdEvaluationFrameworkVersion v=frameworkVersion(agency,id);version(v.getVersion(),r.recordVersion());if(levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrderAsc(agency,id).isEmpty())throw new IllegalLifecycleTransitionException("At least one evaluation level is required before publication");LdEvaluationFrameworkVersion prior=v.getSupersedesId()==null?null:frameworkVersion(agency,v.getSupersedesId());validatePublish(r,prior,frameworkVersions.findByAgencyIdAndStatus(agency,LdDefinitionStatus.PUBLISHED),v.getId());EvaluationFrameworkResponse before=frameworkResponse(agency,v);Instant now=Instant.now();v.publish(r.effectiveFrom(),r.effectiveTo(),audit.currentActor(),now);v=frameworkVersions.saveAndFlush(v);if(prior!=null){prior.supersede(r.effectiveFrom(),audit.currentActor(),now);frameworkVersions.saveAndFlush(prior);}EvaluationFrameworkResponse after=frameworkResponse(agency,v);audit.record(agency,"PUBLISH_LD_EVALUATION_FRAMEWORK","LD_EVALUATION_FRAMEWORK_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}
 @Override public EvaluationFrameworkResponse retireEvaluationFramework(String agency,String id,DefinitionTransition r,String c){LdEvaluationFrameworkVersion v=frameworkVersion(agency,id);version(v.getVersion(),r.recordVersion());EvaluationFrameworkResponse before=frameworkResponse(agency,v);v.retire(audit.currentActor(),r.reason(),Instant.now());v=frameworkVersions.saveAndFlush(v);EvaluationFrameworkResponse after=frameworkResponse(agency,v);audit.record(agency,"RETIRE_LD_EVALUATION_FRAMEWORK","LD_EVALUATION_FRAMEWORK_VERSION",id,v.getDefinitionVersion(),v.getVersion(),before,after,r.reason(),c);return after;}
 @Override @Transactional(readOnly=true)public EvaluationFrameworkResponse effectiveEvaluationFramework(String agency,LocalDate on){return frameworkVersions.findByAgencyIdAndStatus(agency,LdDefinitionStatus.PUBLISHED).stream().filter(v->v.effectiveOn(on)).findFirst().map(v->frameworkResponse(agency,v)).orElseThrow(()->new ResourceNotFoundException("No L&D evaluation framework is effective on the requested date"));}

 private LdGovernancePolicyVersion policyVersion(String a,String id){return policyVersions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D governance policy version not found"));}private LdGovernancePolicy policyRoot(String a,String id){return policies.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D governance policy not found"));}
 private LdInterventionVersion interventionVersion(String a,String id){return interventionVersions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D intervention version not found"));}private LdIntervention interventionRoot(String a,String id){return interventions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D intervention not found"));}
 private LdProvider providerEntity(String a,String id){return providers.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D provider not found"));}private LdResourcePerson resourcePersonEntity(String a,String id){return resourcePersons.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D resource person not found"));}
 private LdEvaluationFrameworkVersion frameworkVersion(String a,String id){return frameworkVersions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D evaluation framework version not found"));}private LdEvaluationFramework frameworkRoot(String a,String id){return frameworks.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D evaluation framework not found"));}
 private void validateProvider(String a,String id){if(id!=null){LdProvider p=providerEntity(a,id);if(p.getStatus()!=LdProvider.Status.ACTIVE)throw new IllegalArgumentException("An active provider is required");}}
 private static void validateLevels(List<EvaluationLevelInput> values){Set<LdEvaluationLevel.Type>types=new HashSet<>();Set<Integer>orders=new HashSet<>();for(EvaluationLevelInput v:values){if(!types.add(v.levelType()))throw new IllegalArgumentException("Evaluation level types must be unique");if(!orders.add(v.displayOrder()))throw new IllegalArgumentException("Evaluation level display orders must be unique");}}
 private static void validatePublish(PublishTransition r,LdVersionedDefinition prior,List<? extends LdVersionedDefinition> published,String current){if(r.effectiveTo()!=null&&r.effectiveTo().isBefore(r.effectiveFrom()))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");if(prior!=null&&!r.effectiveFrom().isAfter(prior.getEffectiveFrom()))throw new IllegalArgumentException("A revision must become effective after its predecessor");LocalDate to=r.effectiveTo()==null?LocalDate.MAX:r.effectiveTo();boolean overlap=published.stream().filter(x->!x.getId().equals(current)).filter(x->prior==null||!x.getId().equals(prior.getId())).anyMatch(x->!to.isBefore(x.getEffectiveFrom())&&(x.getEffectiveTo()==null||!r.effectiveFrom().isAfter(x.getEffectiveTo())));if(overlap)throw new IllegalArgumentException("A published definition is already effective in the requested interval");}
 private static void version(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}private static void newRecord(Long v){if(v!=null)throw new IllegalArgumentException("recordVersion must not be supplied when creating");}private static void stableCode(String existing,String supplied){if(!existing.equalsIgnoreCase(supplied.trim()))throw new IllegalArgumentException("Definition code is stable; create a separate definition for a new code");}private static String normalize(String v){return v.trim().toUpperCase(Locale.ROOT);}private static void published(LdDefinitionStatus s){if(s!=LdDefinitionStatus.PUBLISHED)throw new IllegalLifecycleTransitionException("Only a published definition can have a revision");}
 private int nextPolicyVersion(String a,String id){return policyVersions.findByAgencyIdAndPolicyIdOrderByDefinitionVersionDesc(a,id).stream().mapToInt(LdGovernancePolicyVersion::getDefinitionVersion).max().orElse(0)+1;}
 private LdGovernancePolicyVersion policyVersion(String a,String id,int n,String prior,PolicyInput r){return new LdGovernancePolicyVersion(a,id,n,prior,r.title(),r.description(),r.legalBasis(),r.planningYearStartMonth(),r.minimumPlannedInterventions(),r.supervisoryMinimumHours(),r.behaviorEvaluationMinDays(),r.behaviorEvaluationMaxDays(),r.requiresIdp(),r.requiresSupervisorRecommendation(),r.requiresFinalApproval());}private LdInterventionVersion interventionVersion(String a,String id,int n,String prior,InterventionInput r){return new LdInterventionVersion(a,id,n,prior,r.title(),r.description(),r.category(),r.defaultModality(),r.intendedOutcomes(),r.deliveryRequirements());}
 private PolicyResponse policyResponse(String a,LdGovernancePolicyVersion v){LdGovernancePolicy p=policyRoot(a,v.getPolicyId());return new PolicyResponse(v.getId(),p.getId(),p.getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getPlanningYearStartMonth(),v.getMinimumPlannedInterventions(),v.getSupervisoryMinimumHours(),v.getBehaviorEvaluationMinDays(),v.getBehaviorEvaluationMaxDays(),v.isRequiresIdp(),v.isRequiresSupervisorRecommendation(),v.isRequiresFinalApproval(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getPublishedBy(),v.getPublishedAt(),v.getRetiredBy(),v.getRetiredAt(),v.getRetirementReason(),v.getVersion());}
 private InterventionResponse interventionResponse(String a,LdInterventionVersion v){LdIntervention i=interventionRoot(a,v.getInterventionId());return new InterventionResponse(v.getId(),i.getId(),i.getCode(),v.getTitle(),v.getDescription(),v.getCategory().name(),v.getDefaultModality().name(),v.getIntendedOutcomes(),v.getDeliveryRequirements(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getPublishedBy(),v.getPublishedAt(),v.getRetiredBy(),v.getRetiredAt(),v.getRetirementReason(),v.getVersion());}
 private ProviderResponse providerResponse(LdProvider p){return new ProviderResponse(p.getId(),p.getCode(),p.getName(),p.getProviderType().name(),p.getAccreditationReference(),p.getContactDetails(),p.getStatus().name(),p.getVersion());}private ResourcePersonResponse resourcePersonResponse(LdResourcePerson p){return new ResourcePersonResponse(p.getId(),p.getCode(),p.getPersonSource().name(),p.getEmployeeNo(),p.getDisplayName(),p.getProviderId(),p.getExpertise(),p.getCredentials(),p.getContactDetails(),p.getStatus().name(),p.getVersion());}
 private EvaluationFrameworkResponse frameworkResponse(String a,LdEvaluationFrameworkVersion v){LdEvaluationFramework f=frameworkRoot(a,v.getFrameworkId());List<EvaluationLevelResponse>items=levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrderAsc(a,v.getId()).stream().map(x->new EvaluationLevelResponse(x.getId(),x.getLevelType().name(),x.isRequired(),x.getDueAfterDays(),x.getScoreMethod().name(),x.getPassingScore(),x.getEvidenceRequirements(),x.getInstrumentGuidance(),x.getDisplayOrder())).toList();return new EvaluationFrameworkResponse(v.getId(),f.getId(),f.getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getLevelRevision(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getPublishedBy(),v.getPublishedAt(),v.getRetiredBy(),v.getRetiredAt(),v.getRetirementReason(),v.getVersion(),items);}
 private void record(String agency,String action,String type,LdVersionedDefinition v,Object after,Object before,String c){audit.record(agency,action,type,v.getId(),v.getDefinitionVersion(),v.getVersion(),before,after,null,c);}private void record(String agency,String action,String type,com.primehr.rsp.domain.RspAuditedEntity v,Object after,Object before,String c){audit.record(agency,action,type,v.getId(),null,v.getVersion(),before,after,null,c);}
}
